class Circle {
    constructor(radius) {
        this._radius = radius;
    }
    set radius(r) {
        if (r > 0) this._radius = r;
    }
    get area() {
        return 3.14 * this._radius * this._radius;
    }
}

const c = new Circle(2);
c.radius = 3;
console.log(c.area.toFixed(2));
